import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"حقیقت کو بنیاد بنانے کا بنیادی موقف","description":"","frontmatter":{},"headers":[],"relativePath":"ur/09-现实为基根本立场.md","filePath":"ur/09-现实为基根本立场.md"}'),d={name:"ur/09-现实为基根本立场.md"};function h(l,t,i,u,n,q){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="حقیقت-کو-بنیاد-بنانے-کا-بنیادی-موقف" tabindex="-1">حقیقت کو بنیاد بنانے کا بنیادی موقف <a class="header-anchor" href="#حقیقت-کو-بنیاد-بنانے-کا-بنیادی-موقف" aria-label="Permalink to &quot;حقیقت کو بنیاد بنانے کا بنیادی موقف&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>09</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>حقیقت کو بنیاد بنانا، واحد حقیقت، خیالی حد، قوانین کی تازہ کاری، عملی تصدیق</td></tr></tbody></table><h2 id="اولًا-حقیقت-کو-بنیاد-بنانے-کی-بنیادی-تعریف" tabindex="-1">اولًا. حقیقت کو بنیاد بنانے کی بنیادی تعریف <a class="header-anchor" href="#اولًا-حقیقت-کو-بنیاد-بنانے-کی-بنیادی-تعریف" aria-label="Permalink to &quot;اولًا. حقیقت کو بنیاد بنانے کی بنیادی تعریف&quot;">​</a></h2><p>حقیقت کو بنیاد بنانا لنگر سمبیوٹک تہذیب کا بنیادی علمی موقف اور طریقہ کار کا اصول ہے، جس کا مطلب ہے کہ تہذیب کے تمام نظریاتی ڈھانچے، ادارہ جاتی ڈیزائن، سادھائی کی مشق، اور تکنیکی جدت کو حقیقی دنیا کو واحد حقیقی بنیاد اور حتمی تصدیقی معیار کے طور پر لینا چاہیے۔ &quot;حقیقت&quot; سے مراد مادی دنیا اور توانائی کی دنیا کی حقیقی موجودگی ہے جسے سمجھا جا سکتا ہے، ناپا جا سکتا ہے، تصدیق کیا جا سکتا ہے، اور یہ زندگی کی بقا اور ارتقاء کی حقیقی جگہ ہے۔</p><p>حقیقت کو بنیاد بنانے کے موقف میں تین سطحوں کے معنی شامل ہیں: پہلا، حقیقی دنیا واحد حقیقی دنیا ہے، اور خیالی دنیا (جس میں ناول، افسانے، اور خیالی دنیا شامل ہیں) ذہنی تجربات کی پیداوار ہیں اور ان کی کوئی حقیقی حقیقت نہیں ہے؛ دوسرا، خیالی دنیا کی ترتیبات کو تحریک کے ذرائع اور ذہنی تجربات کے آلات کے طور پر استعمال کیا جا سکتا ہے، لیکن براہ راست حقیقت کی بنیاد کے طور پر استعمال نہیں کیا جا سکتا، اور انہیں حقیقی قوانین کی تصدیق اور تبدیلی سے گزرنا ہوگا؛ تیسرا، وہ چیزیں جو ابھی حقیقت میں موجود نہیں ہیں، انہیں پہلے سے تصدیق شدہ حقیقی قوانین کی بنیاد پر معقول اندازہ لگایا اور تخلیق کیا جا سکتا ہے، لیکن اس تخلیق کو مشق کی تصدیق قبول کرنی ہوگی۔</p><h2 id="ثانیًا-کیوں-حقیقت-کو-بنیاد-بنانے-پر-اصرار-کرنا-چاہیے" tabindex="-1">ثانیًا. کیوں حقیقت کو بنیاد بنانے پر اصرار کرنا چاہیے <a class="header-anchor" href="#ثانیًا-کیوں-حقیقت-کو-بنیاد-بنانے-پر-اصرار-کرنا-چاہیے" aria-label="Permalink to &quot;ثانیًا. کیوں حقیقت کو بنیاد بنانے پر اصرار کرنا چاہیے&quot;">​</a></h2><h3 id="_2-1-خیال-اور-حقیقت-کے-درمیان-الجھن-کو-روکنا" tabindex="-1">2.1 خیال اور حقیقت کے درمیان الجھن کو روکنا <a class="header-anchor" href="#_2-1-خیال-اور-حقیقت-کے-درمیان-الجھن-کو-روکنا" aria-label="Permalink to &quot;2.1 خیال اور حقیقت کے درمیان الجھن کو روکنا&quot;">​</a></h3><p>سادھائی کی تہذیب میں، خیالی دنیا کی ترتیبات اکثر مضبوط کشش رکھتی ہیں۔ بہت سے سادھک ناولوں، افسانوں اور داستانوں سے سادھائی کی تحریک حاصل کرتے ہیں، جو خود میں معمول کی بات ہے۔ لیکن اگر خیالی دنیا کی ترتیبات کو براہ راست حقیقی قوانین کے برابر قرار دیا جائے، تو یہ سنگین مسائل کا باعث بنے گا: خیالی ترتیبات کے مطابق سادھائی کرنے سے سادھائی میں انحراف ہو سکتا ہے، خیالی ترتیبات کی بنیاد پر ادارے بنانے سے حقیقت سے علیحدگی ہو سکتی ہے، خیالی کرداروں کو حقیقی بتوں کے طور پر لینے سے ذہنی الجھن ہو سکتی ہے۔ حقیقت کو بنیاد بنانے کے موقف کا بنیادی کام خیال اور حقیقت کے درمیان حد واضح کرنا ہے، اور دونوں کی الجھن کو روکنا ہے۔</p><h3 id="_2-2-سادھائی-کی-مشق-کی-حفاظت-اور-تاثیر-کو-یقینی-بنانا" tabindex="-1">2.2 سادھائی کی مشق کی حفاظت اور تاثیر کو یقینی بنانا <a class="header-anchor" href="#_2-2-سادھائی-کی-مشق-کی-حفاظت-اور-تاثیر-کو-یقینی-بنانا" aria-label="Permalink to &quot;2.2 سادھائی کی مشق کی حفاظت اور تاثیر کو یقینی بنانا&quot;">​</a></h3><p>سادھائی ایک سنجیدہ مشق ہے جس میں زندگی کی ابتدا اور توانائی کا چلانہ شامل ہے، اور کوئی بھی غلط نظریہ سنگین نتائج کا باعث بن سکتا ہے۔ خیالی دنیا کے سادھائی کے نظام اکثر مصنفین کی کہانی کی ضرورت کے لیے ڈیزائن کیے جاتے ہیں، اور وہ حقیقی توانائی کے چلانے کے قوانین اور زندگی کے ارتقاء کے قوانین سے مطابقت نہیں رکھتے۔ اگر سادھک بغیر تفریق کے خیالی ترتیبات کی نقل کرتے ہیں، تو معمول کے معاملے میں سادھائی غیر موثر ہوگی اور وقت ضائع ہوگا، سنگین معاملات میں توانائی کی خرابی، سادھائی میں انحراف، اور یہاں تک کہ جان کا خطرہ بھی ہو سکتا ہے۔ حقیقت کو بنیاد بنانے کا موقف تقاضا کرتا ہے کہ تمام سادھائی کے نظریات حقیقت کی تصدیق اور توثیق سے گزرے، اور سادھائی کی مشق کی حفاظت اور تاثیر کو یقینی بنائے۔</p><h3 id="_2-3-تہذیب-کے-اداروں-کی-عملیت-کو-برقرار-رکھنا" tabindex="-1">2.3 تہذیب کے اداروں کی عملیت کو برقرار رکھنا <a class="header-anchor" href="#_2-3-تہذیب-کے-اداروں-کی-عملیت-کو-برقرار-رکھنا" aria-label="Permalink to &quot;2.3 تہذیب کے اداروں کی عملیت کو برقرار رکھنا&quot;">​</a></h3><p>تہذیب کے اداروں کا ڈیزائن حقیقی سماجی حالات، وسائل کی صورت حال، اور نسلی تعلقات جیسے حقیقی عوامل پر مبنی ہونا چاہیے۔ اگر حقیقت سے علیحدہ ہو کر، صرف خوبصورت تخیلات یا خیالی ترتیبات کی بنیاد پر ادارے ڈیزائن کیے جائیں، تو ادارے ہوا میں بنے محل بن جائیں گے اور عملی طور پر نافذ نہیں کیے جا سکیں گے۔ حقیقت کو بنیاد بنانے کا موقف تقاضا کرتا ہے کہ تمام ادارہ جاتی ڈیزائن حقیقت سے شروع ہوں، مشق کی تصدیق سے گزرے، اور حقیقت کی تبدیلیوں کے مطابق مسلسل ایڈجسٹ اور بہتر بنائے جائیں۔</p><h3 id="_2-4-جدت-اور-تخلیق-کے-لیے-قابل-اعتماد-طریقہ-کار-فراہم-کرنا" tabindex="-1">2.4 جدت اور تخلیق کے لیے قابل اعتماد طریقہ کار فراہم کرنا <a class="header-anchor" href="#_2-4-جدت-اور-تخلیق-کے-لیے-قابل-اعتماد-طریقہ-کار-فراہم-کرنا" aria-label="Permalink to &quot;2.4 جدت اور تخلیق کے لیے قابل اعتماد طریقہ کار فراہم کرنا&quot;">​</a></h3><p>حقیقت کو بنیاد بنانے کا مطلب جدت اور تخیل کو محدود کرنا نہیں ہے، بلکہ جدت اور تخیل کے لیے قابل اعتماد طریقہ کار فراہم کرنا ہے۔ خیال کو تحریک کے ذرائع اور ذہنی تجربات کے آلات کے طور پر استعمال کیا جا سکتا ہے، لیکن حقیقی تخلیق حقیقی قوانین کی گہری سمجھ پر مبنی ہونی چاہیے۔ وہ چیزیں جو حقیقت میں نہیں ہیں، جب تک وہ حقیقی قوانین سے مطابقت رکھتی ہیں، انہیں تخلیق کیا جا سکتا ہے؛ لیکن اگر وہ حقیقی قوانین کی خلاف ورزی کرتی ہیں، تو تخیل چاہے جتنی بھی خوبصورت ہو، وہ حقیقت نہیں بن سکتی۔ حقیقت کو بنیاد بنانے کا موقف &quot;جرات مندانہ تخیل&quot; اور &quot;محتاط تصدیق&quot; کو یکجا کرتا ہے، اور جدت کو مضبوط بنیاد پر قائم کرتا ہے۔</p><h2 id="ثالثًا-خیال-اور-حقیقت-کے-تعلق-کو-سنبھالنے-کے-اصول" tabindex="-1">ثالثًا. خیال اور حقیقت کے تعلق کو سنبھالنے کے اصول <a class="header-anchor" href="#ثالثًا-خیال-اور-حقیقت-کے-تعلق-کو-سنبھالنے-کے-اصول" aria-label="Permalink to &quot;ثالثًا. خیال اور حقیقت کے تعلق کو سنبھالنے کے اصول&quot;">​</a></h2><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th><th>مخصوص تقاضے</th></tr></thead><tbody><tr><td>تفریق کا اصول</td><td>خیالی ترتیبات اور حقیقی قوانین کو سختی سے الگ کریں</td><td>کسی بھی نظریے میں واضح طور پر بتانا چاہیے کہ اس کی ابتدا خیالی تحریک ہے یا حقیقی تصدیق</td></tr><tr><td>جذب کا اصول</td><td>خیال کو تحریک کے ذرائع اور ذہنی تجربے کے طور پر استعمال کیا جا سکتا ہے</td><td>خیال سے تحریک حاصل کرنے کی حوصلہ افزائی کریں، لیکن حقیقی قوانین کی تبدیلی سے گزرنا ضروری ہے</td></tr><tr><td>تصدیق کا اصول</td><td>تمام نظریات کو حقیقی مشق کی تصدیق سے گزرنا ضروری ہے</td><td>غیر تصدیق شدہ نظریات صرف مفروضے کے طور پر استعمال کیے جا سکتے ہیں، مشق کی رہنمائی کی بنیاد کے طور پر نہیں</td></tr><tr><td>تبدیلی کا اصول</td><td>خیالی ترتیبات کو حقیقی قوانین سے مطابقت رکھنے والی شکل میں تبدیل کرنا ضروری ہے</td><td>خیال کے تصورات کو حقیقی توانائی سائنس اور قانون سائنس کی زبان میں دوبارہ بیان کریں</td></tr><tr><td>حد کا اصول</td><td>خیالی دنیا کے حقوق اور واجبات حقیقت میں پھیلتے نہیں ہیں</td><td>خیالی دنیا کی شناخت، معاہدوں، اور وجہ و نتیجے کی حقیقت میں درستگی کو تسلیم نہ کریں</td></tr></tbody></table><h2 id="رابعًا-خیال-کی-کمی-کو-حقیقت-سے-پورا-کریں،-جو-حقیقت-میں-نہیں-ہے-اسے-قوانین-کی-تازہ-کاری-کی-بنیاد-پر-تخلیق-کریں" tabindex="-1">رابعًا. &quot;خیال کی کمی کو حقیقت سے پورا کریں، جو حقیقت میں نہیں ہے اسے قوانین کی تازہ کاری کی بنیاد پر تخلیق کریں&quot; <a class="header-anchor" href="#رابعًا-خیال-کی-کمی-کو-حقیقت-سے-پورا-کریں،-جو-حقیقت-میں-نہیں-ہے-اسے-قوانین-کی-تازہ-کاری-کی-بنیاد-پر-تخلیق-کریں" aria-label="Permalink to &quot;رابعًا. &quot;خیال کی کمی کو حقیقت سے پورا کریں، جو حقیقت میں نہیں ہے اسے قوانین کی تازہ کاری کی بنیاد پر تخلیق کریں&quot;&quot;">​</a></h2><p>یہ حقیقت کو بنیاد بنانے کے موقف کا بنیادی آپریشنل اصول ہے، اور اس میں دو پہلو شامل ہیں:</p><h3 id="_4-1-خیال-کی-کمی-کو-حقیقت-سے-پورا-کریں" tabindex="-1">4.1 خیال کی کمی کو حقیقت سے پورا کریں <a class="header-anchor" href="#_4-1-خیال-کی-کمی-کو-حقیقت-سے-پورا-کریں" aria-label="Permalink to &quot;4.1 خیال کی کمی کو حقیقت سے پورا کریں&quot;">​</a></h3><p>جب خیالی دنیا سے حاصل کردہ تحریک یا ترتیبات کافی مکمل نہ ہوں، خود مطابقت نہ رکھتی ہوں، یا حقیقی قوانین سے مطابقت نہ رکھتی ہوں، تو انہیں حقیقت میں پہلے سے تصدیق شدہ علم اور قوانین کا استعمال کرتے ہوئے پورا اور درست کیا جانا چاہیے۔ مثال کے طور پر، کوئی خاص خیالی سادھائی کا نظام صرف سطحوں کی تقسیم کو بیان کر سکتا ہے لیکن توانائی کے چلانے کے طریقہ کار کی وضاحت نہ کر سکتا ہے، تو اس صورت میں حقیقی توانائی کے چکر کے نظریے کا استعمال کرتے ہوئے اس کے چلانے کے طریقہ کار کو پورا کرنا ضروری ہے؛ کوئی خاص خیالی ٹیکنالوجی توانائی کے تحفظ کے بنیادی قانون کی خلاف ورزی کر سکتی ہے، تو اس صورت میں حقیقی قوانین کا استعمال کرتے ہوئے اس کی ترتیب کو درست کرنا ضروری ہے۔</p><p>پورا کرنے کا عمل صرف خیال اور حقیقت کو ایک ساتھ جوڑنا نہیں ہے، بلکہ حقیقی قوانین کو ڈھانچے کے طور پر لینا، خیال کے معقول عناصر کو دوبارہ ترتیب دے کر ایک خود مطابقت رکھنے والے اور حقیقی قوانین سے مطابقت رکھنے والے نظریاتی نظام میں تبدیل کرنا ہے۔</p><h3 id="_4-2-جو-حقیقت-میں-نہیں-ہے-اسے-قوانین-کی-تازہ-کاری-کی-بنیاد-پر-تخلیق-کریں" tabindex="-1">4.2 جو حقیقت میں نہیں ہے اسے قوانین کی تازہ کاری کی بنیاد پر تخلیق کریں <a class="header-anchor" href="#_4-2-جو-حقیقت-میں-نہیں-ہے-اسے-قوانین-کی-تازہ-کاری-کی-بنیاد-پر-تخلیق-کریں" aria-label="Permalink to &quot;4.2 جو حقیقت میں نہیں ہے اسے قوانین کی تازہ کاری کی بنیاد پر تخلیق کریں&quot;">​</a></h3><p>جب کوئی خاص چیز یا صلاحیت ابھی حقیقت میں موجود نہ ہو، لیکن اس کے وجود کا امکان پہلے سے تصدیق شدہ حقیقی قوانین کی بنیاد پر اندازہ کیا جا سکے، تو اسے قوانین کی بنیاد پر معقول انداز میں تازہ کاری اور تخلیق کیا جا سکتا ہے۔ یہ تخلیق بغیر بنیاد کے تخیل نہیں ہے، بلکہ موجودہ قوانین کی بنیاد پر منطقی توسیع اور تکنیکی نفاذ ہے۔</p><p>مثال کے طور پر، دوگنا پھلوں کی تکنیکی اطلاق &quot;قوانین کی تازہ کاری کی بنیاد پر تخلیق&quot; کا ایک عام معاملہ ہے۔ دوگنا پھل ابتدائی طور پر خیالی کاموں کی ترتیب سے آیا تھا، لیکن سمبیوٹک تہذیب کے محققین نے اس کے بنیادی طریقہ کار (دوگنا افزائش) کو حقیقی توانائی سائنس اور قانون سائنس کی زبان میں دوبارہ بیان کیا، اور توانائی کی افزائش اور قانون کی گونج کے قوانین کی بنیاد پر، ایک ایسی دوگنا ٹیکنالوجی تیار کی جسے انجینئرنگ کے ذریعے نافذ کیا جا سکتا ہے۔ اس عمل نے خیالی تحریک کا استعمال کیا اور ساتھ ہی سختی سے حقیقی قوانین پر عمل کیا۔</p><p>تخلیق کے نتائج کو مشق کی تصدیق سے گزرنا ضروری ہے۔ صرف وہی تخلیق جو حقیقت میں موثر، محفوظ، اور مستقل کے طور پر تصدیق کی گئی ہے، اسے سمبیوٹک تہذیب کے رسمی نظام میں شامل کیا جا سکتا ہے۔</p><h2 id="خامسًا-مختلف-شعبوں-میں-حقیقت-کو-بنیاد-بنانے-کا-اطلاق" tabindex="-1">خامسًا. مختلف شعبوں میں حقیقت کو بنیاد بنانے کا اطلاق <a class="header-anchor" href="#خامسًا-مختلف-شعبوں-میں-حقیقت-کو-بنیاد-بنانے-کا-اطلاق" aria-label="Permalink to &quot;خامسًا. مختلف شعبوں میں حقیقت کو بنیاد بنانے کا اطلاق&quot;">​</a></h2><h3 id="_5-1-سادھائی-کے-شعبے-میں" tabindex="-1">5.1 سادھائی کے شعبے میں <a class="header-anchor" href="#_5-1-سادھائی-کے-شعبے-میں" aria-label="Permalink to &quot;5.1 سادھائی کے شعبے میں&quot;">​</a></h3><p>تمام سادھائی کے نظام کو &quot;حقیقی تصدیق&quot; کے عمل سے گزرنا ضروری ہے: نظریاتی تعمیر سے شروع کرتے ہوئے چھوٹے پیمانے پر تجربات، اور پھر بڑے پیمانے پر فروغ، ہر مرحلے میں قابل پیمائش اور قابل تکرار اثرات کا ڈیٹا ہونا ضروری ہے۔ وہ سادھائی کے طریقے جو حقیقی تصدیق سے نہیں گزرے، انہیں صرف &quot;تجرباتی طریقے&quot; کے طور پر استعمال کیا جا سکتا ہے، خطرے کی نشاندہی کے ساتھ، اور رسمی طریقے کے طور پر فروغ نہیں دیا جا سکتا۔</p><h3 id="_5-2-ٹیکنالوجی-کے-شعبے-میں" tabindex="-1">5.2 ٹیکنالوجی کے شعبے میں <a class="header-anchor" href="#_5-2-ٹیکنالوجی-کے-شعبے-میں" aria-label="Permalink to &quot;5.2 ٹیکنالوجی کے شعبے میں&quot;">​</a></h3><p>تمام قانون کی انجینئرنگ ٹیکنالوجیز کو &quot;نظریاتی طور پر ممکن — تجرباتی تصدیق — انجینئرنگ نفاذ — حفاظتی تشخیص&quot; کے ترقیاتی عمل پر عمل کرنا ضروری ہے۔ ٹیکنالوجی کا نظریاتی بنیاد پہلے سے تصدیق شدہ حقیقی قانون ہونا چاہیے، ٹیکنالوجی کے اثرات کے قابل پیمائش اشارے ہونے چاہیئں، اور ٹیکنالوجی کی حفاظت کو سخت تشخیص سے گزرنا ضروری ہے۔</p><h3 id="_5-3-سماجی-اداروں-کے-شعبے-میں" tabindex="-1">5.3 سماجی اداروں کے شعبے میں <a class="header-anchor" href="#_5-3-سماجی-اداروں-کے-شعبے-میں" aria-label="Permalink to &quot;5.3 سماجی اداروں کے شعبے میں&quot;">​</a></h3><p>تمام سماجی اداروں کے ڈیزائن حقیقی سماجی تحقیقات اور ڈیٹا تجزیے پر مبنی ہونے چاہیئں۔ بڑے ادارہ جاتی تبدیلیوں کو پہلے چھوٹے پیمانے پر آزمائش کرنی چاہیے، اور اثرات کی تشخیص کے بعد بتدریج فروغ دینا چاہیے۔ اداروں کی تشخیص کے معیار قابل پیمائش حقیقی اشارے ہونے چاہیئں، خلاصہ تصورات یا خیالی ترتیبات نہیں۔</p><h3 id="_5-4-تاریخ-اور-آثار-قدیمہ-کے-شعبے-میں" tabindex="-1">5.4 تاریخ اور آثار قدیمہ کے شعبے میں <a class="header-anchor" href="#_5-4-تاریخ-اور-آثار-قدیمہ-کے-شعبے-میں" aria-label="Permalink to &quot;5.4 تاریخ اور آثار قدیمہ کے شعبے میں&quot;">​</a></h3><p>تاریخی واقعات اور قدیم تہذیبوں کی تحقیق حقیقی شواہد اور قابل تصدیق تاریخی مواد پر مبنی ہونی چاہیے۔ داستانوں اور افسانوں کے مواد کو ثقافتی تحقیق کے موضوع کے طور پر استعمال کیا جا سکتا ہے، لیکن براہ راست تاریخی حقیقت کے طور پر تسلیم نہیں کیا جا سکتا۔ آثار قدیمہ کا کام &quot;کاپی آئینہ + الگ تھلگ مختلف جگہ پر آثار قدیمہ، صرف علم کی واپسی&quot; کے کم آلودگی منصوبے پر عمل کرتا ہے، اور اس بات کو یقینی بناتا ہے کہ آثار قدیمہ کا کام تاریخی حقیقت کو تبدیل نہیں کرتا۔</p><h2 id="سادسًا-حقیقت-کے-تصور-کی-گہری-سمجھ" tabindex="-1">سادسًا. &quot;حقیقت&quot; کے تصور کی گہری سمجھ <a class="header-anchor" href="#سادسًا-حقیقت-کے-تصور-کی-گہری-سمجھ" aria-label="Permalink to &quot;سادسًا. &quot;حقیقت&quot; کے تصور کی گہری سمجھ&quot;">​</a></h2><p>خاص طور پر یہ بتانا ضروری ہے کہ حقیقت کو بنیاد بنانے کے موقف میں &quot;حقیقت&quot; ایک جامد، بند تصور نہیں ہے، بلکہ یہ ایک متحرک تصور ہے جسے مسلسل سمجھا اور وسعت دیا جا رہا ہے۔</p><p>پہلا، حقیقت کا دائرہ تہذیب کی ترقی کے ساتھ ساتھ مسلسل وسعت پاتا ہے۔ وہ مظاہر جو ماضی میں &quot;فطری سے بالاتر&quot; سمجھے جاتے تھے، توانائی اور قوانین کی گہری سمجھ کے ساتھ، حقیقت کے دائرے میں شامل ہو گئے ہیں۔ لنگر میکانزم، جہتوں کے درمیان سفر، شعور کے ڈومین کی تعامل وغیرہ، کم تہذیب کے نقطہ نظر سے شاید &quot;خیالی&quot; لگ سکتے ہیں، لیکن اعلیٰ تہذیب کی حقیقت میں یہ حقیقی طور پر موجود ہیں۔</p><p>دوسرا، حقیقی قوانین کی سمجھ مسلسل گہری ہو رہی ہے۔ وہ نظریات جو آج &quot;قانون&quot; سمجھے جاتے ہیں، مستقبل میں مزید گہرے نظریات کی طرف سے درست یا بدل دئے جا سکتے ہیں۔ حقیقت کو بنیاد بنانے کا موقف کا مطلب موجودہ سمجھ کو سختی سے برقرار رکھنا نہیں ہے، بلکہ &quot;مشق کو سچائی کی تصدیق کا واحد معیار&quot; کے بنیادی طریقے کو مضبوطی سے پکڑے رکھنا ہے، اور حقیقت کی سمجھ کو مسلسل گہرا کرنا ہے۔</p><p>تیسرا، حقیقت میں لامحدود امکانات شامل ہیں۔ موجودہ قوانین کی بنیاد پر، ہم بہت سی ایسی امکانات کا اندازہ لگا سکتے ہیں جو ابھی تک حاصل نہیں ہوئیں، اور انہیں تکنیکی ذرائع کے ذریعے حقیقت میں بدل سکتے ہیں۔ حقیقت کو بنیاد بنانے کا مطلب امکانات کو محدود کرنا نہیں ہے، بلکہ اس بات کو یقینی بنانا ہے کہ امکانات کا نفاذ قابل اعتماد بنیاد پر قائم ہو۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>حقیقت کو بنیاد بنانا لنگر سمبیوٹک تہذیب کا بنیادی موقف ہے، اور یہ تہذیب کے تمام نظریات اور مشق کا نقطہ آغاز اور منزل ہے۔ یہ تقاضا کرتا ہے کہ ہمارے پاس کھلی تخیل ہونی چاہیے، خیال اور داستانوں سے تحریک حاصل کریں؛ اور ساتھ ہی سخت عملی جذبہ ہونا چاہیے، تمام تحریکوں کو حقیقی قوانین کی تصدیق کے تحت رکھیں۔ خیال کی کمی کو حقیقت سے پورا کریں، جو حقیقت میں نہیں ہے اسے قوانین کی تازہ کاری کی بنیاد پر تخلیق کریں — یہ اصول تخیل اور حقیقت، تحریک اور قانون، تخلیق اور تصدیق کو نامیاتی طور پر یکجا کرتا ہے، اور سمبیوٹک تہذیب کی مسلسل ارتقاء کے لیے قابل اعتماد طریقہ کار کی ضمانت فراہم کرتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (ہینگ یوآن ژو کائنات کا عمومی جائزہ)</li><li>16-倍增果实技术化原理 (دوگنا پھلوں کی تکنیکی بنیاد)</li><li>84-考古协议总纲 (آثار قدیمہ کے معاہدے کا عمومی منصوبہ)</li></ul>',43)])])}const c=a(d,[["render",h]]);export{p as __pageData,c as default};
